MultiLanguageSpellData['it'][1218316] = {name = "Corruzione degli Aspetti", additional_info = "1.5 s di lancio\n[q]Evoca e congeda la Corruzione degli Aspetti, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q]\"Con il trionfo di N'zoth, ciò che ebbe inizio con Galakrond ora giunge a compimento e, con la scomparsa degli Aspetti, la corruzione della loro specie è completa.\"\nMercante:\nTori\nZona:\nDornogal\nCosto:\n40.000"}
MultiLanguageSpellData['it'][1218317] = {name = "Pantera di Cristallo del Vuoto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda una Pantera di Cristallo del Vuoto cavalcabile.\n[q]\"Sebbene molte gemme preziose siano state corrotte dalle energie del vuoto nelle Visioni Orripilanti, i maestri orefici possono ancora utilizzarle per realizzare possenti pantere cavalcabili.\"\nProfessione:\nOreficeria"}
