MultiLanguageSpellData['it'][1226531] = {name = "Ricciospino Estivo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Ricciospini Estivi amano crogiolarsi al sole o farsi una nuotata in un lago limpido. Sono abilissimi nella raccolta di cibo, ma vanno convinti a farlo.\"\nEmporio"}
MultiLanguageSpellData['it'][1226532] = {name = "Ricciospino Invernale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Ricciospini Invernali sono creature principalmente notturne. Sono leggermente più lenti degli altri ricciospini, ma la loro resistenza non ha eguali.\"\nEmporio"}
MultiLanguageSpellData['it'][1226533] = {name = "Ricciospino Autunnale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Ricciospini Autunnali sono impareggiabili nel fiutare il cibo nei mesi più freddi. Il loro olfatto sensibilissimo li rende compagni eccellenti per la raccolta di cibo nelle foreste, ma diventano difficili da controllare in ambienti più aromatici.\"\nEmporio"}
