MultiLanguageSpellData['it'][1233515] = {name = "Deposito Informazioni Sicure a Controllo Ottimale", additional_info = "[q0][Item Effect][q]Gli incantesimi e le abilità hanno una probabilità di trasformarti in un Parafulmine che colpisce un bersaglio nemico casuale entro 40 m, infliggendo ( 1 * 209 ) danni da natura ogni 3 s per 15 s."}
MultiLanguageSpellData['it'][1233518] = {name = "K'arroc Lavanda", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Il precedente padrone di questo k'arroc particolarmente aggressivo è morto mentre esplorava lo Spazio Slegato. Forse adesso accetterà te... o forse no.\"\nMercante:\nShad'anis\nZona:\nK'aresh\nCosto:\n10"}
