MultiLanguageSpellData['it'][1233547] = {name = "Strisciante del Vuoto Acido", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questo strisciante ha consumato svariati fumi nocivi e ora il suo corpo è infuso di potenti acidi.\"\nMercante:\nShad'anis\nZona:\nK'aresh\nCosto:\n7"}
