MultiLanguageSpellData['it'][1233942] = {name = "Condotto del Vento a Favore", additional_info = "Portata illimitata\nIstantaneo\n[q]Genera una scarica di velocità quando si esce dal combattimento, aumentando la velocità di movimento del 100% per 10 s. L'efficacia diminuisce nel tempo. Usare un'abilità di difesa quando si è in combattimento circonda di folate di vento, fornendo uno scudo per 8 s pari al 50% della salute mancante.\n(30s di recupero)"}
MultiLanguageSpellData['it'][1233945] = {name = "Cristallo d'Amplificazione Audio", additional_info = "Portata illimitata\nIstantaneo\n[q]La voce di Brann viene straordinariamente amplificata dalla magia arcana, così che le sue parole forniscano potenzialmente al gruppo un beneficio in base a ciò che dice."}
MultiLanguageSpellData['it'][1233946] = {name = "Egida Rovinata", additional_info = "Portata illimitata\nIstantaneo\n[q]Quando l'egida è equipaggiata, aumenta tutti i danni inflitti e le cure fornite dai membri del gruppo del 12%. Ogni 10 s durante il combattimento, tu e Brann rigenerate salute pari al 20% dei danni subiti in questo lasso di tempo.\n\n Quando un personaggio muore, l'egida ne riduce i danni subiti del 4% e ne aumenta le cure ricevute del 5% alla resurrezione, ma ne riduce i danni inflitti e le cure fornite del 4%. Si accumula fino a 3 volte."}
MultiLanguageSpellData['it'][1233947] = {name = "Cristallo di Decelerazione Temporale", additional_info = "Portata illimitata\nIstantaneo\n[q]Infliggere danni a un nemico élite che ha almeno il 80% di salute oppure il 20% o meno di salute fa sì che Brann attivi le energie del cristallo, riducendo la velocità d'attacco e di lancio d'incantesimi dell'élite del 50% per 30 s. Uccidere l'élite bersaglio mentre la penalità è attiva fornisce al gruppo un beneficio cumulabile del 8% alla celerità."}
MultiLanguageSpellData['it'][1233948] = {name = "Dispositivo Interrogativo", additional_info = "Portata illimitata\nIstantaneo\nCirca 2 apparenze ogni minuto\n[q]Brann ha una probabilità di aumentare del 20% la salute dei personaggi, i danni che infliggono o le cure che forniscono per 20 s in base al ruolo di combattimento che ha scelto.\n\n I personaggi hanno una probabilità di aumentare del 20% la salute di Brann, i danni che infligge o le cure che fornisce per 20 s in base al ruolo che hanno scelto.\n(20s di recupero)"}
