MultiLanguageSpellData['it'][1235387] = {name = "Frusta Mistica di Naazindhri", additional_info = "Frusta Mistica di Naazindhri Livello 80\n[q0][Item Effect]Circa 2.5 apparenze ogni minuto\n[q]Gli incantesimi d'attacco hanno un'alta probabilità di colpire il bersaglio con il potere arcano, infliggendo ( 467 * 1 ) danni da arcano suddivisi tra il bersaglio e i nemici colpiti sulla traiettoria.\n\n I danni inflitti aumentano del 30% per ogni nemico aggiuntivo, fino a un massimo del 150%, e vengono aumentati ulteriormente dalla maestria."}
MultiLanguageSpellData['it'][1235388] = {name = "Ira Bestiale", additional_info = "Portata di 100 m\nIstantaneo\n[q]Le Bestie Feroci obbediscono a Ordine di Morte, infliggendo i suoi danni al 30% dell'efficacia.\n\n Ira Bestiale fa infuriare le Bestie Feroci, aumentandone i danni inflitti del 15% per 15 s. Le Bestie Feroci evocate durante Ira Bestiale ne beneficiano per una durata ridotta."}
MultiLanguageSpellData['it'][1235391] = {name = "Trasformazione Oscura", additional_info = "Portata di 100 m\nIstantaneo\n[q]Il tuo [ Sputafango : abominio ] [ Glifo - Geist : geist / ghoul ] infligge ([44.73% of Attack Power]) danni da ombra a 5 nemici vicini e si trasforma in una potente mostruosità non morta per 15 s, [ Trasformazione Oscura : aumentando la propria energia del 100% e ]ottenendo abilità potenziate, così da assumere nuove funzioni finché la trasformazione è attiva."}
MultiLanguageSpellData['it'][1235397] = {name = "Portata Ombrale", additional_info = "[q]Affinità Animale\n Aumenta i danni periodici inflitti da Freccia Nera del 100% e Polvere Cupa applica l'effetto periodico di Freccia Nera a tutti i nemici che danneggia.\n\n Se Polvere Cupa infligge danni a 2 o più nemici, fornisce Fendente Bestiale, se si è scelto il relativo talento.\n\nPrecisione di Tiro\n Aumenta i danni periodici inflitti da Freccia Nera del 100% e Polvere Cupa applica l'effetto periodico di Freccia Nera a tutti i nemici che danneggia.\n\n Se Polvere Cupa infligge danni a 2 o più nemici, fornisce Tiri Ingannevoli, se si è scelto il relativo talento."}
