MultiLanguageSpellData['it'][1235934] = {name = "Martello della Luce", additional_info = "Portata di 100 m\nIstantaneo\n[q]Colpisce il nemico con il potere della Luce, infliggendo ([580.645% of Attack Power]) danni da sacro e ([290% of Attack Power]) danni da sacro a un massimo di 4 nemici vicini.\n\n Inoltre, richiama dei Martelli Empirei dal cielo che colpiscono 3 nemici vicini, infliggendo ([46.55% of Attack Power]) danni da sacro ciascuno."}
MultiLanguageSpellData['it'][1235946] = {name = "Amuleto dell'Ira Incessante", additional_info = "[q0][Item Effect]Istantaneo\n[q]Subire danni fa infuriare, permettendo di assorbire 202 danni subiti e infliggere 461 danni da ombra suddivisi tra i nemici vicini per ogni accumulo di Infuriato. Danni inflitti aumentati del 30% per ogni nemico aggiuntivo, fino a un massimo del 150%.\n\n Gli accumuli di Infuriato si sommano ogni 15 s, fino a un massimo di 15 volte, ma ci si calma rapidamente dopo aver lasciato il combattimento.\n\nValido solo per le specializzazioni da difensore."}
MultiLanguageSpellData['it'][1235959] = {name = "Mage Spellslinger 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Arcano\n Aumenta i danni inflitti da Detonazione Arcana del 12% e Detonazione Arcana fornisce 1 accumulo di Armonia Arcana. I danni diretti inflitti da una Scheggia hanno una probabilità del 25% di fornire 1 accumulo di Armonia Arcana.\n\nFuoco, Gelo\n Aumenta i danni inflitti da Lancia di Ghiaccio e Frammenti di Ghiaccio del 10% e Lancia di Ghiaccio ha una probabilità del 50% di fornire 1 accumulo di Fronte Gelido. I danni diretti inflitti da una Scheggia hanno una probabilità del 15% di fornire 1 accumulo di Fronte Gelido."}
MultiLanguageSpellData['it'][1235962] = {name = "Mage Sunfury 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Arcano, Fuoco, Gelo\n Bonus ai danni magici fornito da Sfera di Fuocoincanto aumentato del 1.0%. Cascata di Mana aumenta la celerità del 0.5% aggiuntivo per ogni accumulo."}
MultiLanguageSpellData['it'][1235963] = {name = "Mage Frostfire 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Arcano, Gelo\n Aumenta i danni inflitti da Meteora e Scarica di Fuocogelo del 30%. Aumenta i danni inflitti da Palla di Fuocogelo del 10%. Meteora, Scarica di Fuocogelo e Palla di Fuocogelo applicano Incendio, infliggendo il 25% di danni aggiuntivi in 9 s.\n\nFuoco\n Aumenta i danni inflitti da Tempesta di Comete e Scarica di Fuocogelo del 15%. Aumenta i danni inflitti da Palla di Fuocogelo del 8%. Tempesta di Comete, Scarica di Fuocogelo e Palla di Fuocogelo applicano Incendio al 75% dell'efficacia."}
MultiLanguageSpellData['it'][1235964] = {name = "Mage Spellslinger 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Arcano\n Aumenta i danni inflitti dalle Schegge del 8%. Globo Arcano ha una probabilità del 100% di fornire 1 accumulo di Armonia Arcana, fino a un massimo di 8 volte. Al raggiungimento di 20 accumuli di Armonia Arcana, si ottiene Intuizione al 100% dell'efficacia.\n\nFuoco\n Aumenta i danni inflitti dalle Schegge del 8%. Globo Arcano ha una probabilità del 100% di fornire 1 accumulo di Armonia Arcana, fino a un massimo di 8 volte. Quando Fronte Gelido evoca un Globo Congelato, aumenta i danni magici inflitti del 8% per 10 s.\n\nGelo\n Quando Globo Congelato infligge danni a uno o più nemici, ha una probabilità del 15% di fornire 1 accumulo di Fronte Gelido. Quando Fronte Gelido evoca un Globo Congelato, aumenta i danni magici inflitti del 8% per 10 s.\n\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1235965] = {name = "Mage Sunfury 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Fuoco, Gelo\n Gli incantesimi eccezionali lanciati dalla Fenice aggiungono 0.3 s alla durata della successiva Ipertermia. Quando la Fenice termina, ti potenzia ulteriormente, attivando una Distorsione Temporale Inferiore e aumentando i danni magici inflitti del 10% per 10 s.\n\nArcano\n Gli incantesimi eccezionali lanciati dalla Fenice aggiungono 0.5 s alla durata della successiva Anima Arcana. Quando la Fenice termina, ti potenzia ulteriormente, attivando una Distorsione Temporale Inferiore e aumentando i danni magici inflitti del 20% per 10 s."}
MultiLanguageSpellData['it'][1235966] = {name = "Mage Frostfire 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Arcano, Gelo\n Lanciare Aculeo Glaciale ha una probabilità del 100% di lanciare anche Pirosfera, infliggendo ([352.5% of Spell Power]) danni da fuoco. Inoltre, Pirosfera beneficia di Incendio.\n\nFuoco\n Lanciare Pirosfera ha una probabilità del 20% di lanciare anche Aculeo Glaciale, infliggendo ([366.24% of Spell Power]) danni da gelo. Aculeo Glaciale lanciato in questo modo non immobilizza il bersaglio. Inoltre, Aculeo Glaciale beneficia di Incendio."}
