MultiLanguageSpellData['it'][1236253] = {name = "Death Knight Deathbringer 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Lanciare Marchio della Mietitrice fornisce [2][1] accumulo di Sterminio al [150][150]% dell'efficacia della prima falce e al [125][125]% dell'efficacia della seconda falce."}
MultiLanguageSpellData['it'][1236254] = {name = "Death Knight Deathbringer 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Sangue, Gelo, Empietà\n Aumenta i danni inflitti da Sterminio del 20% e il numero massimo di accumuli di Marchio della Mietitrice di 15. Quando esplode, Marchio della Mietitrice aumenta la probabilità di critico del 10% per 8 s.\n(1s di recupero)"}
MultiLanguageSpellData['it'][1236256] = {name = "Fendente Vorpal", additional_info = "Portata di 10 m\n2.5 s di lancio\n[q]L'incantatore fende l'area frontale, infliggendo danni da ombra e applicando un effetto d'assorbimento delle cure ai personaggi colpiti."}
MultiLanguageSpellData['it'][1236259] = {name = "Death Knight San'layn 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Empietà\n Imposizione del Dolore estende la durata dei tuoi effetti di malattia di 3.0 s aggiuntivi sul bersaglio principale. Essenza della Regina del Sangue aumenta anche la maestria del 0.5% per accumulo.\n\nSangue, Gelo\n Imposizione del Dolore estende la durata dei tuoi effetti di malattia di 4.0 s aggiuntivi sul bersaglio principale. Essenza della Regina del Sangue aumenta anche la maestria del 0.5% per accumulo."}
MultiLanguageSpellData['it'][1236260] = {name = "Death Knight San'layn 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Empietà\n Aumenta i danni inflitti da Imposizione del Dolore del 30% e Assalto Vampirico aumenta i danni inflitti dal tuo Ghoul del 20% per 8 s. Applicazioni multiple potrebbero sovrapporsi.\n\nSangue, Gelo\n Aumenta i danni inflitti da Imposizione del Dolore del 50% e Assalto Vampirico aumenta i danni inflitti da Armi Runiche Danzanti del 20% per 8 s. Applicazioni multiple potrebbero sovrapporsi."}
MultiLanguageSpellData['it'][1236262] = {name = "Serpente Saggio di Shaohao", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli insegnamenti appresi da Shaohao durante la vita e nella morte e la passione che nutriva per la propria casa si sono coagulati in questo serpente etereo, un riflesso della saggezza dell'Imperatore.\"\nPromozione:\nMists of Pandaria Classic"}
MultiLanguageSpellData['it'][1236263] = {name = "Folgore Arcana", additional_info = "Portata di 30 m\n1.75 s di lancio\n[q]Inflicts 5 Arcane damage to an enemy."}
MultiLanguageSpellData['it'][1236272] = {name = "Catena Critica", additional_info = "Istantaneo\nCirca 1.5 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare Sovraccarico Critico, aumentando l'indice di critico di 39 ogni 2 s per 20 s.\n(20s di recupero)"}
MultiLanguageSpellData['it'][1236273] = {name = "Scoppio di Scintille", additional_info = "Istantaneo\nCirca 1.5 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare uno Scoppio di Scintille, aumentando l'indice di celerità di 174 per 20 s."}
MultiLanguageSpellData['it'][1236275] = {name = "Carica Statica", additional_info = "Istantaneo\nCirca 1.5 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di fornire Carica Statica, aumentando l'indice di versatilità di ( 17 * 20) per 30 s. Ogni successivo lancio di un incantesimo o abilità riduce la versatilità aggiuntiva del 5%.\n(29s di recupero)"}
MultiLanguageSpellData['it'][1236276] = {name = "Corrente Elettrica", additional_info = "Istantaneo\n[q]All'inizio del combattimento si ottiene Corrente Elettrica, che aumenta l'indice di maestria di 10 ogni 2 s, fino a un massimo di (12 * 10 ) dopo 24 s, quindi il ciclo ricomincia e si ripete."}
MultiLanguageSpellData['it'][1236277] = {name = "Tocco Caricato", additional_info = "Istantaneo\nCirca 2 apparenze ogni minuto\n[q]Fornire cure fornisce una probabilità che la Scintilla salti sul bersaglio con meno salute entro 40 m, curandolo di 1766 ."}
MultiLanguageSpellData['it'][1236278] = {name = "Scudo Energetico", additional_info = "Istantaneo\nCirca 1.5 apparenze ogni minuto\n[q]Subire danni fornisce una probabilità di ottenere uno Scudo Energetico Titanico, che impedisce fino a 3662 danni subiti per 10 s. Quando lo scudo termina, infligge danni da arcano pari al 30% dell'effetto d'assorbimento restante suddivisi tra i nemici entro 8 m."}
MultiLanguageSpellData['it'][1236279] = {name = "Cristallo Caricato", additional_info = "Istantaneo\nCirca 1.5 apparenze ogni minuto\n[q]Gli incantesimi e gli attacchi hanno una probabilità di lanciare un Dardo Caricato contro un bersaglio, infliggendo 1206 danni da natura suddivisi tra i bersagli entro 8 m."}
