MultiLanguageSpellData['it'][1236330] = {name = "Druid Druid of the Claw 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Aggressore Ferino\n Devastazione ha una probabilità del 40% di lanciare Devastazione una seconda volta sullo stesso bersaglio dopo 4 s al 100% del potere iniziale.\n\nEquilibrio, Guardiano Ferino, Rigenerazione\n Devastazione ha una probabilità del 40% di lanciare Devastazione una seconda volta sullo stesso bersaglio dopo 4 s al 60% dell'efficacia."}
MultiLanguageSpellData['it'][1236331] = {name = "Druid Druid of the Claw 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Devastazione aumenta la celerità del 10%, aumenta la probabilità di critico del 10% e aumenta i danni da sanguinamento inflitti del 30% per 5 s.\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1236332] = {name = "Druid Elune's Chosen 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aggressore Ferino, Guardiano Ferino, Rigenerazione\n Aumenta i danni inflitti da Falciata del 20%. Falciata ha una probabilità del 40% di lancare una Cometa Arcana su un bersaglio al 160% dell'efficacia.\n\nEquilibrio\n Aumenta i danni inflitti da Fuoco Stellare del 25%. Generare potere astrale con Fuoco Stellare ha una probabilità del 50% di lancare una Cometa Arcana su un bersaglio al 50% dell'efficacia.\n\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1236333] = {name = "Druid Elune's Chosen 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Aggressore Ferino, Guardiano Ferino, Rigenerazione\n All'impatto, le Comete Arcane lanciate da Falciata si dividono su massimo 3 bersaglio aggiuntivo al 20% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Raggio Lunare consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s.\n\nEquilibrio\n All'impatto, le Comete Arcane lanciate da Fuoco Stellare si dividono su massimo 3 bersaglio aggiuntivo al 80% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Furia di Elune o Luna Piena consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s."}
MultiLanguageSpellData['it'][1236334] = {name = "Druid Keeper of the Grove 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Equilibrio, Aggressore Ferino, Guardiano Ferino\n Lanciare Allineamento Celeste richiama in aiuto una Driade per 10 s che lancia Cometa Arcana al 360% dell'efficacia e Pioggia di Stelle al 800% dell'efficacia.\n\nRigenerazione\n Lanciare Incarnazione: Albero della Vita o Convocazione degli Spiriti richiama in aiuto una Driade per 5 s che lancia Tranquillità al 50% dell'efficacia e Ricrescita sull'alleato con meno salute al 200% dell'efficacia."}
MultiLanguageSpellData['it'][1236336] = {name = "Druid Keeper of the Grove 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Equilibrio, Aggressore Ferino, Guardiano Ferino\n Quando la Driade scompare, 2 successivo lancio di Cometa Arcana infligge danni aggiuntivi pari al 2% dei danni inflitti quand'era attiva e diffonde il 10% dei danni inflitti su nemici vicini. Cure e danni ridotti oltre 5 bersagli.\n\nRigenerazione\n Quando la Driade scompare, 2 successivo lancio di Guarigione Immediata fornisce cure aggiuntive pari al 5% delle cure fornite quand'era attiva e diffonde il 25% delle cure fornite su alleati vicini. Cure e danni ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][1236337] = {name = "Druid Wildstalker 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Equilibrio, Guardiano Ferino, Rigenerazione\n Aumenta la velocità alla quale l'effetto Boccioli Simbiotici cresce del 30%. Lanciare Ricrescita con Lancio Istintivo fa sì che l'effetto Boccioli Simbiotici cresca su massimo 2 alleati vicini idonei.\n\nAggressore Ferino\n Aumenta la velocità alla quale l'effetto Viticci Succhiasangue cresce del 40%. Furia della Tigre fa sì che l'effetto Viticci Succhiasangue cresca su massimo 3 nemici vicini idonei."}
MultiLanguageSpellData['it'][1236338] = {name = "Druid Wildstalker 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Equilibrio, Guardiano Ferino, Rigenerazione\n L'effetto Boccioli Simbiotici ha una probabilità del 20% di attivare Crescita Esplosiva ogni 2 s al 80% dell'efficacia. Ogni accumulo di Boccioli Simbiotici su un alleato aumenta le cure fornite da Crescita Esplosiva del 30%.\n\nAggressore Ferino\n L'effetto Viticci Succhiasangue ha una probabilità del 20% di attivare Crescita Esplosiva ogni 2 s al 100% dell'efficacia. Ogni accumulo di Viticci Succhiasangue su un nemico aumenta i danni inflitti da Crescita Esplosiva del 40%."}
MultiLanguageSpellData['it'][1236342] = {name = "Preparazione all'Assalto", additional_info = "[q0][Item Effect]Istantaneo\n[q]Aggressore Ferino\nDevastazione ha una probabilità del 40% di lanciare Devastazione una seconda volta sullo stesso bersaglio dopo 4 s al 100% del potere iniziale.\n\nEquilibrio, Guardiano Ferino, Rigenerazione\nDevastazione ha una probabilità del 40% di lanciare Devastazione una seconda volta sullo stesso bersaglio dopo 4 s al 60% dell'efficacia."}
