MultiLanguageSpellData['it'][1236348] = {name = "Taglio Caricato", additional_info = "Portata di 100 m\n{4 s di lancio} {3 s di recupero}\n[q]Zo'phex carica le spade e scatena un fendente massiccio, infliggendo 15758921 danni fisici a tutti i nemici frontali."}
MultiLanguageSpellData['it'][1236350] = {name = "Void Power Shard Released Visuals - COSMETIC", additional_info = nil}
MultiLanguageSpellData['it'][1236354] = {name = "Aspirazione dell'Anima", additional_info = "Portata di 40 m\n{2 s di lancio} {5 s di recupero}\n[q]L'incantatore rallenta il bersaglio e prosciuga 622547 salute in 8 s, curando l'incantatore del doppio dell'ammontare prosciugato."}
MultiLanguageSpellData['it'][1236355] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Sangue, Empietà\n Apocalisse evoca Biancachioma per 10 s. Aumenta i danni inflitti da Non Morte di Biancachioma del 20%, i bersagli infettati quando si diffonde di 1 e i danni inflitti da Spira Mortale di Biancachioma del 35%.\n\nGelo\n Pilastro di Ghiaccio evoca Cacciatroll per 10 s. Aumenta i danni inflitti da Furia Gelida di Cacciatroll del 20% e quelli inflitti da Disintegrazione di Cacciatroll del 35%."}
MultiLanguageSpellData['it'][1236356] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Gelo\n Lanciare Disintegrazione o Falce del Signore del Gelo ordina a Cacciatroll di lanciare Disintegrazione o Falce del Signore del Gelo al 100% dell'efficacia. La tua Disintegrazione infligge il 20% di danni aggiuntivi ai bersagli affetti da Furia Gelida di Cacciatroll.\n\nSangue, Empietà\n Lanciare Spira Mortale o Epidemia ordina a Biancachioma di lanciare Spira Mortale o Epidemia al 125% dell'efficacia. La tua Spira Mortale infligge il 40% di danni aggiuntivi ai bersagli affetti da Non Morte di Biancachioma.\n\n(500ms di recupero)"}
MultiLanguageSpellData['it'][1236358] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Lame del Razziatore del 50% e gli altri danni unicamente fisici inflitti del 25%."}
MultiLanguageSpellData['it'][1236360] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Vendetta\n Furia degli Aldrachi potenzia ulteriormente Fendente d'Anima se lanciato dopo Recisione, aumentandone i colpi a 12.\n\n Marchio della Mietitrice si accumula fino a 2 volte e potenzia ulteriormente Recisione se lanciato dopo Fendente d'Anima, applicando 1 accumulo aggiuntivo al 100% della durata normale.\n\nRovina\n Furia degli Aldrachi potenzia ulteriormente Lame Danzanti se lanciato dopo Assalto del Caos, aumentandone i colpi a 12.\n\n Marchio della Mietitrice si accumula fino a 2 volte e potenzia ulteriormente Assalto del Caos se lanciato dopo Lame Danzanti, applicando 1 accumulo aggiuntivo al 100% della durata normale."}
MultiLanguageSpellData['it'][1236361] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Rovina\n Aumenta i danni inflitti da Rogo Rovente del 30% e aumenta i danni inflitti da Assalto del Caos del 20% quando è attivo.\n\nVendetta\n Aumenta i danni inflitti da Rogo Rovente del 30% e aumenta i danni inflitti da Fendente d'Anima del 20% quando è attivo."}
MultiLanguageSpellData['it'][1236362] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Rovina\n Attivare la Forma Demoniaca provoca istantaneamente un Impeto Demoniaco e rilascia un Frammento dell'Anima di Demone che aumenta i danni inflitti del 20% per 10 s.\n\nVendetta\n Attivare la Forma Demoniaca provoca istantaneamente un Impeto Demoniaco e rilascia un Frammento dell'Anima di Demone che aumenta i danni inflitti del 20% per 15 s.\n\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1236364] = {name = "Evoker Flameshaper 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Avvolgimento alimenta Fiamma Interiore, aumentando i danni periodici inflitti e le cure periodiche fornite del 25% e aumentando la probabilità di ottenere Detonazione dell'Essenza del 50% per 12 s. Si accumula fino a 2 volte. Applicazioni multiple potrebbero sovrapporsi."}
MultiLanguageSpellData['it'][1236365] = {name = "Evoker Flameshaper 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Conservazione, Fortificazione\n Consumare Detonazione dell'Essenza durante Fiamma Interiore lancia una Bomba d'Essenza contro il bersaglio, fornendo ([250% of Spell Power]) cure agli alleati vicini, quantità ridotta oltre 5 bersagli.\n\nDevastazione\n Consumare Detonazione dell'Essenza durante Fiamma Interiore lancia una Bomba d'Essenza contro il bersaglio, infliggendo ([371% of Spell Power]) danni da arcano ai nemici vicini, quantità ridotta oltre 5 bersagli."}
MultiLanguageSpellData['it'][1236366] = {name = "Evoker Scalecommander 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Fortificazione\n Quando si vola durante Alito del Drago e per 20 s dopo il termine, si comanda uno squadrone di 2 Dracthyr che attacca i bersagli con Disintegrazione e Pira.\n\nDevastazione, Conservazione\n Quando si vola durante Alito del Drago e per 10 s dopo il termine, si comanda uno squadrone di 2 Dracthyr che attacca i bersagli con Disintegrazione e Pira."}
MultiLanguageSpellData['it'][1236367] = {name = "Evoker Scalecommander 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Devastazione\n Quando lo squadrone è attivo, Disintegrazione di Massa colpisce fino a 2 bersaglio aggiuntivo. Inoltre, lo squadrone persiste per 5 s aggiuntivi.\n\nFortificazione\n Quando lo squadrone è attivo, Eruzione di Massa colpisce fino a 2 bersaglio aggiuntivo. Inoltre, lo squadrone persiste per 10 s aggiuntivi.\n\nConservazione\n Quando lo squadrone è attivo, Eruzione di Massa colpisce fino a 2 bersaglio aggiuntivo. Inoltre, lo squadrone persiste per 5 s aggiuntivi."}
MultiLanguageSpellData['it'][1236368] = {name = "Evoker Chronowarden 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Riduce il tempo di recupero di Ago della Bilancia di 60 s."}
MultiLanguageSpellData['it'][1236369] = {name = "Evoker Chronowarden 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Temporal Burst causes Chrono Flames to strike 2 additional target and repeat 15% additional damage or healing, up to a maximum of [(Potenza Magica * 4.5) * (1 + Versatilità)], and increases Essence ability damage and healing by 30%."}
MultiLanguageSpellData['it'][1236370] = {name = "Hunter Dark Ranger 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Precisione di Tiro, Sopravvivenza\n Aumenta i danni inflitti da Freccia Nera del 10% e quelli inflitti da Polvere Cupa del 20%. Riduce il tempo di recupero di Precisione di 30 s.\n\nAffinità Animale\n Aumenta i danni inflitti da Freccia Nera del 10% e quelli inflitti da Polvere Cupa del 20%. Riduce il tempo di recupero di Richiamo Selvaggio di 60 s."}
MultiLanguageSpellData['it'][1236371] = {name = "Hunter Dark Ranger 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Affinità Animale, Precisione di Tiro, Sopravvivenza\n Aumenta i danni inflitti da Freccia Nera del Fuoco Indebolente del 50%. Consumare Colpo Mortale ha una probabilità del 50% di far sì che tutte le raffiche di Freccia Nera durante il successivo Fuoco Indebolente scaglino 1 Freccia Nera aggiuntiva."}
MultiLanguageSpellData['it'][1236372] = {name = "Hunter Pack Leader 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Precisione di Tiro, Sopravvivenza\n Aumenta i danni inflitti dai famigli del 15% e i danni inflitti dalle Bestie del 15%. Evocare una Bestia aumenta la celerità, la maestria o la probabilità di critico del 6%, in base alla Bestia evocata, per 8 s.\n\nAffinità Animale\n Aumenta i danni inflitti dai famigli del 5% e i danni inflitti dalle Bestie del 15%. Evocare una Bestia aumenta la celerità, la maestria o la probabilità di critico del 6%, in base alla Bestia evocata, per 8 s."}
MultiLanguageSpellData['it'][1236373] = {name = "Hunter Pack Leader 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Evocare una Bestia sotto gli effetti di Comando dalla Prima Linea agita la fauna selvatica nelle vicinanze e provoca un Impeto che la induce a caricare il bersaglio, infliggendo [([300% of Attack Power]) * 9] danni fisici a massimo 8 nemici in 7 s."}
MultiLanguageSpellData['it'][1236374] = {name = "Hunter Sentinel 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Affinità Animale, Sopravvivenza\n Aumenta i danni inflitti da Bomba di Fuocobrado del 10%. Quando Tempesta Lunare termina, fornisce Dono di Elune, che fa sì che 2 lanci successivi di Bomba di Fuocobrado infliggano danni da arcano e i danni iniziali inflitti siano aumentati del 150%.\n\nPrecisione di Tiro\n Aumenta i danni inflitti da Rapidità di Tiro del 25%. Quando Tempesta Lunare termina, fornisce Dono di Elune, che fa sì che 2 lanci successivi di Tiro Mirato infliggano danni da arcano e i danni inflitti siano aumentati del 10%."}
MultiLanguageSpellData['it'][1236375] = {name = "Hunter Sentinel 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Precisione di Tiro\n Aumenta i danni inflitti da Sentinella del 18%. Dono di Elune resta attivo per la durata di Tempesta Lunare al 100% dell'efficacia.\n\nAffinità Animale, Sopravvivenza\n Aumenta i danni inflitti da Sentinella del 20%. Dono di Elune resta attivo per la durata di Tempesta Lunare al 100% dell'efficacia."}
MultiLanguageSpellData['it'][1236376] = {name = "Intreccio dell'Anima", additional_info = nil}
MultiLanguageSpellData['it'][1236377] = {name = "Monk Master of Harmony 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Mastro Birraio\n Ottenere vitalità ha una probabilità crescente di far sì che il successivo Palmo della Tigre scateni un Impeto Armonico, infliggendo [180 * ([400% of Spell Power]) / 100] danni da natura suddivisi tra il bersaglio e gli altri nemici vicini e fornendo [20 * ([500% of Spell Power]) / 100] cure a massimo 5 alleati feriti.\n\nImpeto, Misticismo\n Ottenere vitalità ha una probabilità crescente di far sì che il successivo Palmo della Tigre scateni un Impeto Armonico, infliggendo [20 * ([400% of Spell Power]) / 100] danni da natura suddivisi tra il bersaglio e gli altri nemici vicini e fornendo [90 * ([500% of Spell Power]) / 100] cure a massimo 5 alleati feriti."}
MultiLanguageSpellData['it'][1236378] = {name = "Monk Master of Harmony 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Impeto, Misticismo\n Lanciare Tè della Concentrazione del Tuono garantisce che con 2 lancio successivo di Palmo della Tigre si attivi Impeto Armonico.\n\nMastro Birraio\n Lanciare garantisce che con 2 lancio successivo di Palmo della Tigre si attivi Impeto Armonico."}
MultiLanguageSpellData['it'][1236379] = {name = "Monk Shado-Pan 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Mastro Birraio\n Aumenta i danni inflitti da Assalti a Raffica del 20%. Attivare Armi dell'Ordine fornisce istantaneamente 10 accumulo di Assalti a Raffica che si attivano con il successivo attacco al 70% dell'efficacia.\n\nImpeto, Misticismo\n Aumenta i danni inflitti da Assalti a Raffica del 20%. Attivare Tempesta, Terra e Fuoco fornisce istantaneamente 10 accumulo di Assalti a Raffica che si attivano con il successivo attacco al 70% dell'efficacia."}
MultiLanguageSpellData['it'][1236380] = {name = "Monk Shado-Pan 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Impeto\n Aumenta la generazione di cariche di Raffica di Colpi del 50% e Assalti a Raffica si attiva ogni 120 energia consumata durante Tempesta, Terra e Fuoco.\n\nMastro Birraio, Misticismo\n Aumenta la generazione di cariche di Raffica di Colpi del 50% e Assalti a Raffica si attiva ogni 150 energia consumata durante Armi dell'Ordine."}
MultiLanguageSpellData['it'][1236381] = {name = "Monk Conduit of the Celestials 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Mastro Birraio, Misticismo\n Dopo aver lanciato Tè della Concentrazione del Tuono, Cuore della Serpe di Giada si attiva per 8 s al 100% dell'efficacia.\n\nImpeto\n Dopo aver lanciato Venti Taglienti, Cuore della Serpe di Giada si attiva per 4 s al 100% dell'efficacia.\n\n(1s di recupero)"}
MultiLanguageSpellData['it'][1236382] = {name = "Monk Conduit of the Celestials 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Cuore della Serpe di Giada aumenta la celerità del 10% quando è attivo e per 4 s dopo il termine."}
MultiLanguageSpellData['it'][1236383] = {name = "Paladin Herald of the Sun 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Castigo\n Aumenta le cure fornite e i danni inflitti da Albaluce del 30%. Dopo che Ira Vendicatrice è terminata, fornisce Ira Solare, facendo in modo che l'effetto di Avatar del Sole persista per [10][10] s aggiuntivi.\n\nProtezione\n Aumenta le cure fornite e i danni inflitti da Albaluce del 30%. Dopo che Ira Vendicatrice è terminata, fornisce Ira Solare, facendo in modo che l'effetto di Avatar del Sole persista per [10][10] s aggiuntivi.\n\nSacro (Ira Vendicatrice)\n Aumenta le cure fornite e i danni inflitti da Albaluce del 60%. Dopo che Ira Vendicatrice è terminata, fornisce Ira Solare, facendo in modo che l'effetto di Avatar del Sole persista per 10[10][10] s aggiuntivi."}
MultiLanguageSpellData['it'][1236384] = {name = "Paladin Herald of the Sun 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Castigo\n Ira Solare aumenta l'efficacia delle abilità che consumano cariche di potere sacro del 15% e fornisce [2][2] Albaluce.\n\nProtezione\n Ira Solare aumenta l'efficacia delle abilità che consumano cariche di potere sacro del 15% e fornisce [2][2] Albaluce.\n\nSacro (Ira Vendicatrice)\n Ira Solare aumenta l'efficacia delle abilità che consumano cariche di potere sacro del 30% e fornisce 2[2][2] Albaluce."}
MultiLanguageSpellData['it'][1236385] = {name = "Spostamento dell'Anima", additional_info = nil}
MultiLanguageSpellData['it'][1236389] = {name = "Paladin Lightsmith 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Protezione\n Aumenta i danni inflitti da Incudine e Martello del 15%. L'effetto può essere attivato anche da al 40% dell'efficacia.\n\nCastigo\n Aumenta le cure fornite da Incudine e Martello del 15%. L'effetto può essere attivato anche da Assalto del Crociato al 40% dell'efficacia.\n\nSacro\n Aumenta le cure fornite da Incudine e Martello del 15%. L'effetto può essere attivato anche da Assalto del Crociato al 75% dell'efficacia.\n\n(750ms di recupero)"}
MultiLanguageSpellData['it'][1236390] = {name = "Paladin Lightsmith 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Incudine e Martello fornisce 1 accumulo di Capolavoro, in modo tale che il successivo lancio di Armamenti Sacri lanci anche una versione Inferiore dell'incantesimo su un alleato vicino per ogni accumulo."}
MultiLanguageSpellData['it'][1236391] = {name = "Paladin Templar 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aumenta i danni critici inflitti da Martello Empireo del 20% e i suoi colpi critici hanno una probabilità del 50% di fornire 1 accumulo aggiuntivo di Salvezza della Luce.\n(Possibilità di Apparire:50%)"}
MultiLanguageSpellData['it'][1236392] = {name = "Paladin Templar 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Sacro, Protezione\n Aumenta i danni inflitti da Martello della Luce al bersaglio primario del 35%, aumenta i bersagli secondari colpiti di 3 e aumenta il numero di volte che può essere lanciato dopo Occhio di Tyr di 1.\n\nCastigo\n Aumenta i danni inflitti da Martello della Luce al bersaglio primario del 35%, aumenta i bersagli secondari colpiti di 3 e aumenta il numero di volte che può essere lanciato dopo Scia di Ceneri di 1."}
MultiLanguageSpellData['it'][1236394] = {name = "Priest Oracle 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Sacro, Ombra\nLanciare Preghiera di Guarigione cura il bersaglio di ([1400% of Spell Power]).\n\nDisciplina\n Il primo dardo di ogni Contrizione infligge o fornisce il 200% di danni aggiuntivi o cure aggiuntive."}
MultiLanguageSpellData['it'][1236395] = {name = "Priest Oracle 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Lanciare Premonizione di Pietà o Premonizione di Conforto fornisce 2 accumulo di Premonizione di Consapevolezza al 100% dell'efficacia. Consumare 1 accumulo di Premonizione di Consapevolezza aumenta la celerità del 1.0% per 10 s. Applicazioni multiple potrebbero sovrapporsi."}
MultiLanguageSpellData['it'][1236396] = {name = "Priest Voidweaver 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Sacro\n Aumenta i danni inflitti da Detonazione del Vuoto del 30% e riduce il tempo di lancio di Detonazione del Vuoto del 20%.\n\nOmbra\n Aumenta i danni inflitti da Detonazione del Vuoto del 30% e riduce il tempo di lancio di Detonazione del Vuoto del 20%. Inoltre, riduce il tempo di recupero di Detonazione del Vuoto del 50%.\n\nDisciplina\n Aumenta i danni inflitti da Detonazione del Vuoto e Contrizione del 30% e riduce il tempo di lancio di Detonazione del Vuoto del 20%."}
MultiLanguageSpellData['it'][1236397] = {name = "Priest Voidweaver 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Disciplina\n Detonazione del Vuoto fa crescere Fenditura Entropica. Energia del Vuoto aumenta i danni inflitti da Fenditura Entropica del 10% aggiuntivo e aumenta i danni inflitti dal successivo lancio di Detonazione Mentale di massimo il 200%, in base alle dimensioni della Fenditura Entropica quando collassa.\n\nSacro, Ombra\n Detonazione del Vuoto fa crescere Fenditura Entropica. Energia del Vuoto aumenta i danni inflitti da Fenditura Entropica del 10% aggiuntivo e aumenta i danni inflitti dal successivo lancio di Torrente del Vuoto di massimo il 200%, in base alle dimensioni della Fenditura Entropica quando collassa."}
MultiLanguageSpellData['it'][1236398] = {name = "Priest Archon 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Ombra\n Le Aureole generano 10 pazzia aggiuntiva in 5 s ed Energia Risonante aumenta ulteriormente i danni inflitti da Piaga Divoratrice del 5.0%.\n\nDisciplina, Sacro\n Le Aureole riducono il tempo di recupero della tua Parola Sacra: Serenità e Parola Sacra: Santificazione di 5 s ed Energia Risonante aumenta ulteriormente le cure fornite dalle tue Parole Sacre del 5.0%."}
MultiLanguageSpellData['it'][1236399] = {name = "Priest Archon 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Sacro\n Quando Picco Energetico è attivo, ogni 2 lanci di Parola Sacra: Serenità o Parola Sacra: Santificazione si aggiunge all'effetto un'altra Aureola al 100% dell'efficacia, fino a un massimo di 2 volte.\n\nDisciplina, Ombra\n Quando Picco Energetico è attivo, ogni 2 lanci di Piaga Divoratrice si aggiunge all'effetto un'altra Aureola al 100% dell'efficacia, fino a un massimo di 2 volte."}
MultiLanguageSpellData['it'][1236400] = {name = "Rogue Deathstalker 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Fuorilegge, Scaltrezza\n Simboli di Morte aumenta l'efficacia di tutti gli effetti dannosi di Inseguitore della Morte e dei suoi bonus ai danni del 40% quando l'effetto è attivo.\n\nAssassinio\n Stilettata aumenta l'efficacia di tutti gli effetti dannosi di Inseguitore della Morte e dei suoi bonus ai danni del 60% quando l'effetto è attivo."}
MultiLanguageSpellData['it'][1236401] = {name = "Rogue Deathstalker 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Fuorilegge, Scaltrezza\n Simboli di Morte ha una durata aumentata di 3 s e, all'attivazione, consuma 1 accumulo del Marchio dell'Inseguitore della Morte attivo.\n\nAssassinio\n Stilettata ha una durata aumentata di 3 s e, all'attivazione, consuma 1 accumulo del Marchio dell'Inseguitore della Morte attivo."}
MultiLanguageSpellData['it'][1236402] = {name = "Rogue Fatebound 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Fuorilegge\n Aumenta i danni inflitti da Assalto Spettrale del 50% e la sua durata di 4 s.\n\n Caso Limite lancia una Moneta Vincolafato aggiuntiva e l'attivazione di Assalto Spettrale ne attiva l'effetto.\n\nAssassinio, Scaltrezza\n Aumenta i danni inflitti da Rovina dei Re del 10% e la sua durata di 4 s.\n\n Caso Limite lancia una Moneta Vincolafato aggiuntiva e l'attivazione di Rovina dei Re ne attiva l'effetto."}
MultiLanguageSpellData['it'][1236403] = {name = "Rogue Fatebound 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Fuorilegge\n Un lancio fortunato della Moneta Vincolafato riduce il tempo di recupero di Scarica d'Adrenalina di 30.0 s e di Assalto Spettrale di 15.0 s.\n\nAssassinio, Scaltrezza\n Un lancio fortunato della Moneta Vincolafato riduce il tempo di recupero di Stigma Letale di 30.0 s e di Rovina dei Re di 15.0 s."}
MultiLanguageSpellData['it'][1236404] = {name = "Rogue Trickster 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Lama Invisibile del 35% e gli fornisce una probabilità del 35% di colpire due volte."}
MultiLanguageSpellData['it'][1236405] = {name = "Rogue Trickster 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Colpo di Grazia può essere attivato una seconda volta entro 5 s, infliggendo il 150% dei danni normali."}
MultiLanguageSpellData['it'][1236406] = {name = "Shaman Farseer 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Rapidità Ancestrale evoca per 15 s un Antenato potenziato che infligge o fornisce il 10% di danni aggiuntivi o cure aggiuntive."}
MultiLanguageSpellData['it'][1236407] = {name = "Shaman Farseer 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Elementale, Potenziamento\n Rapidità Ancestrale aumenta i danni inflitti e le cure fornite dagli incantesimi del 25%, riduce il costo in mana degli incantesimi del 25% e aumenta la velocità di ricarica di Getto di Lava del 50% per 8 s.\n\nRigenerazione\n Rapidità Ancestrale aumenta i danni inflitti e le cure fornite dagli incantesimi del 25%, riduce il costo in mana degli incantesimi del 25% e aumenta la velocità di ricarica di Getto di Lava e Marea Benefica del 50% per 8 s."}
MultiLanguageSpellData['it'][1236408] = {name = "Shaman Stormbringer 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Potenziamento, Rigenerazione\n Ascesa ha una probabilità del 100% di fornire una carica di Tempesta e ogni 8 Tempeste Risvegliate si attiva Ascesa per 6.0 s.\n\nElementale\n Ascesa ha una probabilità del 100% di fornire una carica di Tempesta e ogni 9 Tempeste Risvegliate si attiva Ascesa per 6.0 s.\n\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1236409] = {name = "Shaman Stormbringer 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Elementale, Rigenerazione\n Aumenta i danni da natura inflitti del 3.0%. Ascesa potenzia i successivi 2 lanci di Tempesta in modo tale da far concentrare una bufera, che infligge ([960% of Spell Power]) danni da natura al bersaglio primario e danni ridotti ai nemici vicini dopo 1.5 s.\n\nPotenziamento\n Aumenta i danni da natura inflitti del 5.0%. Ascesa potenzia i successivi 2 lanci di Tempesta in modo tale da far concentrare una bufera, che infligge ([400% of Attack Power]) danni da natura al bersaglio primario e danni ridotti ai nemici vicini dopo 1.5 s.\n\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1236410] = {name = "Shaman Totemic 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Potenziamento\n Quando si consumano tutti i Granuli dell'Elemento Turbinante, il Totem Crescente lancia Tempesta Primordiale al 200% dell'efficacia sulla propria posizione.\n\nElementale, Rigenerazione\n Quando si consumano tutti i Granuli dell'Elemento Turbinante, si lancia Nubifragio al 200% dell'efficacia sulla posizione del Totem Crescente."}
MultiLanguageSpellData['it'][1236411] = {name = "Shaman Totemic 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Elementale, Rigenerazione\n Dopo aver lanciato Nubifragio, i successivi lanci di Catena di Guarigione, Ondata di Cura o Eruzione Benefica vengono lanciati di nuovo al 150% dell'efficacia.\n\nPotenziamento\n Dopo aver lanciato Tempesta Primordiale, i successivi lanci di Sferzata Lavica o Esplosione di Fuoco vengono lanciati di nuovo al 150% dell'efficacia.\n\n(500ms di recupero)"}
MultiLanguageSpellData['it'][1236413] = {name = "Warlock Hellcaller 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Demonologia, Distruzione\n Marchio di Xavius aumenta i danni inflitti da Anima Annerita del 3% aggiuntivo per accumulo. Malevolenza aumenta il conteggio degli accumuli di Avvizzimento di 2 accumuli aggiuntivi.\n\nAfflizione\n Marchio di Xavius aumenta i danni inflitti da Anima Annerita del 6% aggiuntivo per accumulo. Malevolenza aumenta il conteggio degli accumuli di Avvizzimento di 2 accumuli aggiuntivi."}
MultiLanguageSpellData['it'][1236414] = {name = "Warlock Hellcaller 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Afflizione\n Lanciare Malevolenza fornisce 2 accumulo di Crescendo Tormentato, impedisce ad Anima Annerita di consumarne gli accumuli e aumenta la velocità alla quale infligge i danni del 25% per 8 s.\n\nDemonologia, Distruzione\n Lanciare Malevolenza fornisce 2 accumulo di Ritorno di Fiamma, impedisce ad Anima Annerita di consumarne gli accumuli e aumenta la velocità alla quale infligge i danni del 15% per 8 s."}
MultiLanguageSpellData['it'][1236415] = {name = "Warlock Soul Harvester 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Ombra di Morte scatena l'Anima Demoniaca contro il bersaglio attuale per 9 s, infliggendo ([279.306% of Spell Power]) danni da ombra istantaneamente e ([186.209% of Spell Power]) danni da ombra aggiuntivi ai nemici entro 10 m a ogni colpo."}
MultiLanguageSpellData['it'][1236416] = {name = "Warlock Soul Harvester 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Anima Demoniaca del 45% e i danni inflitti da Mietitura Malvagia del 45%. L'Anima Demoniaca fornisce 1 frammento d'anima ogni 3 s mentre assale i nemici."}
MultiLanguageSpellData['it'][1236417] = {name = "Warlock Diabolist 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Afflizione, Distruzione\n Il lancio di Dardo del Caos, Pioggia di Fuoco o Combustione dell'Ombra evoca un Oculus Demoniaco, fino a un massimo di 3. Consumare Arte Demoniaca lancia gli Oculi Demoniaci contro il bersaglio attuale, facendoli esplodere e infliggendo ([914.206% of Spell Power]) danni da fuoco istantaneamente e ([609.404% of Spell Power]) danni da fuoco aggiuntivi ai nemici entro 10 m.\n\nDemonologia\n Il lancio di Mano di Gul'dan a piena potenza evoca un Oculus Demoniaco, fino a un massimo di 3. Consumare Arte Demoniaca lancia gli Oculi Demoniaci contro il bersaglio attuale, facendoli esplodere e infliggendo ([914.206% of Spell Power]) danni da fuoco istantaneamente e ([609.404% of Spell Power]) danni da fuoco aggiuntivi ai nemici entro 10 m."}
MultiLanguageSpellData['it'][1236418] = {name = "Warlock Diabolist 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Diversi Oculi Demoniaci analizzano la battaglia e forniscono informazioni quando esplodono, aumentando l'Intelletto del 2% per 10 s."}
MultiLanguageSpellData['it'][1236419] = {name = "Warrior Colossus 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Demolizione del 20%, Inoltre, aumenta i danni critici inflitti dalle abilità di massimo il 20% sui bersagli affetti da una tua Demolizione per 10 s, in base al numero di accumuli di Vigore Colossale consumati."}
MultiLanguageSpellData['it'][1236420] = {name = "Warrior Colossus 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Armi\n Demolizione aumenta la probabilità di critico di 1 lancio successivo di Assalto Mortale del 100%. I colpi critici di Assalto Mortale aumentano i danni inflitti da Squartamento e Ferite Profonde del 80% per 8 s.\n\nFuria, Protezione\n Demolizione aumenta la probabilità di critico di 1 lancio successivo di Colpo di Scudo del 100%. I colpi critici di Colpo di Scudo aumentano i danni inflitti da Squartamento e Ferite Profonde del 80% per 8 s."}
MultiLanguageSpellData['it'][1236421] = {name = "Warrior Mountain Thane 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Boato del Tuono ha una probabilità del 35% di lanciare 5 Assalto Ionizzante sui bersagli affetti. Ogni assalto infligge ([150% of Attack Power]) danni da natura."}
MultiLanguageSpellData['it'][1236422] = {name = "Warrior Mountain Thane 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Assalto Ionizzante del 100%. Quando si attiva, Assalto Ionizzante fornisce 1 carica di Boato del Tuono e aumenta i danni inflitti dal successivo Boato del Tuono del 100%."}
MultiLanguageSpellData['it'][1236423] = {name = "Warrior Slayer 11.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Aumenta i danni inflitti da Esecuzione del 10%. Inoltre, le Esecuzioni di Morte Improvvisa hanno una probabilità del 10% per accumulo di Sopraffatto presente sul bersaglio di attivare Assalto del Carnefice al 100% dell'efficacia."}
MultiLanguageSpellData['it'][1236424] = {name = "Warrior Slayer 11.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Furia, Protezione\n Aumenta i danni inflitti da Colpo Furente del 10%. Inoltre, Colpo Furente ha una probabilità del 2% per accumulo di Sopraffatto presente sul bersaglio di attivare Mietitempesta al 150% dell'efficacia.\n\nArmi\n Aumenta i danni inflitti da Dominazione del 10%. Inoltre, Dominazione ha una probabilità del 2% per accumulo di Sopraffatto presente sul bersaglio di attivare Mietitempesta al 150% dell'efficacia.\n\n(500ms di recupero)"}
MultiLanguageSpellData['it'][1236428] = {name = "Ammirate!", additional_info = "Portata di 100 m\n3 s di lancio\n[q]L'incantatore evoca uno sciame di occhi, ciascuno dei quali lancia un raggio laser che infligge 1045599 danni da ombra ai personaggi frontali."}
MultiLanguageSpellData['it'][1236494] = {name = "Morso", additional_info = "Portata di 40 m\nIstantaneo\n[q]Inflicts Physical damage to an enemy."}
