MultiLanguageSpellData['it'][1236807] = {name = "Favore della Driade", additional_info = "[q0][Item Effect]Istantaneo\n[q]Equilibrio, Aggressore Ferino, Guardiano Ferino\nQuando la Driade scompare, 2 successivo lancio di Cometa Arcana infligge danni aggiuntivi pari al 2% dei danni inflitti quand'era attiva e diffonde il 10% dei danni inflitti su nemici vicini. Cure e danni ridotti oltre 5 bersagli.\n\nRigenerazione\nQuando la Driade scompare, 2 successivo lancio di Guarigione Immediata fornisce cure aggiuntive pari al 5% delle cure fornite quand'era attiva e diffonde il 25% delle cure fornite su alleati vicini. Cure e danni ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][1236822] = {name = "Scatto Sanguinario", additional_info = "[q0][Item Effect]Istantaneo\n[q]Empietà\nAumenta i danni inflitti da Imposizione del Dolore del 30% e Assalto Vampirico aumenta i danni inflitti dal tuo Ghoul del 20% per 8 s. Applicazioni multiple potrebbero sovrapporsi.\n\nSangue, Gelo\nAumenta i danni inflitti da Imposizione del Dolore del 50% e Assalto Vampirico aumenta i danni inflitti da Armi Runiche Danzanti del 20% per 8 s. Applicazioni multiple potrebbero sovrapporsi."}
MultiLanguageSpellData['it'][1236824] = {name = "Nucleo Potenziato", additional_info = "Portata di 300 m\nIstantaneo\n[q]Il nucleo dell'incantatore protegge dai danni subiti. Quando il nucleo viene distrutto, esplode, infliggendo 34853 danni cosmici."}
MultiLanguageSpellData['it'][1236826] = {name = "Set: Completo da Vela della Flotta d'Oro", additional_info = "[q0][Item Effect]Istantaneo\n[q]Ottieni gli aspetti dell'equipaggiamento del set Completo da Vela della Flotta d'Oro."}
MultiLanguageSpellData['it'][1236835] = {name = "Nucleo Esaurito", additional_info = "Portata di 300 m\nIstantaneo\n[q]Il Nucleo Esaurito scatena periodicamente una reazione violenta a causa della mancanza d'energia, infliggendo 34853 danni cosmici a tutti i personaggi ogni 5 s."}
MultiLanguageSpellData['it'][1236836] = {name = "Scheda di Memoria del Deposito Informazioni Sicure a Controllo Ottimale", additional_info = "[q0][Item Effect]Portata illimitata\n3 s di lancio\n[q]Installa la scheda di memoria nel dispositivo DISCO dei Titani, aumentandone il livello oggetto."}
