MultiLanguageSpellData['it'][1236872] = {name = "Soffio Dimensionale", additional_info = "Portata illimitata\nIstantaneo\n[q]L'Ala del Vuoto scatena un raggio galattico dalle sue fauci per 4 s , infliggendo 5621532 danni cosmici a qualsiasi personaggio al suo interno ogni 0.3 s.\n\n Quindi, si aprono diversi portali, dai quali questo respiro viene emesso in altre direzioni."}
MultiLanguageSpellData['it'][1236873] = {name = "Spezzafatuo", additional_info = "Portata illimitata\nIstantaneo\n[q]Salhadaar lancia la sua mazza che rimbalza tra diversi bersagli, infliggendo 24172589 danni da ombra entro 30 m da ogni punto d'impatto."}
