MultiLanguageSpellData['it'][1236886] = {name = "Runa Vantus - Manaforgia Omega", additional_info = "Runa Vantus - Manaforgia Omega Livello 80\n[q0][Item Effect]Portata illimitata\n1.5 s di lancio\n[q]Una volta a settimana, ti sintonizza con le energie del boss della Manaforgia Omega che hai come bersaglio, fornendoti il seguente effetto:\n\nRuna Vantus - Manaforgia Omega\n Aumenta l'indice di versatilità di 1500 quando si combatte contro il boss d'incursione bersaglio. L'effetto dura tutta la settimana."}
MultiLanguageSpellData['it'][1236887] = {name = "Runa Vantus - Manaforgia Omega", additional_info = "Runa Vantus - Manaforgia Omega Livello 80\n[q0][Item Effect]Portata illimitata\n1.5 s di lancio\n[q]Una volta a settimana, ti sintonizza con le energie del boss della Manaforgia Omega che hai come bersaglio, fornendoti il seguente effetto:\n\nRuna Vantus - Manaforgia Omega\n Aumenta l'indice di versatilità di 1700 quando si combatte contro il boss d'incursione bersaglio. L'effetto dura tutta la settimana."}
