MultiLanguageSpellData['it'][1236957] = {name = "Frantumazione Debilitante", additional_info = "Portata di 15 m\n{2 s di lancio} {5 s di recupero}\n[q]L'incantatore carica il colpo e colpisce il bersaglio attuale, infliggendo danni fisici e riducendone tutte le cure ricevute del 10% per 15 s."}
