MultiLanguageSpellData['it'][1236989] = {name = "Raccolta del Chiaro di Luna", additional_info = "[q0][Item Effect]Istantaneo\n[q]Aggressore Ferino, Guardiano Ferino, Rigenerazione\nAll'impatto, le Comete Arcane lanciate da Falciata si dividono su massimo 3 bersaglio aggiuntivo al 20% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Raggio Lunare consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s.\n\nEquilibrio\nAll'impatto, le Comete Arcane lanciate da Fuoco Stellare si dividono su massimo 3 bersaglio aggiuntivo al 80% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Furia di Elune o Luna Piena consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s."}
MultiLanguageSpellData['it'][1236990] = {name = "Soffusione del Chiaro di Luna", additional_info = "[q0][Item Effect]Istantaneo\n[q]Aggressore Ferino, Guardiano Ferino, Rigenerazione\nAll'impatto, le Comete Arcane lanciate da Falciata si dividono su massimo 3 bersaglio aggiuntivo al 20% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Raggio Lunare consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s.\n\nEquilibrio\nAll'impatto, le Comete Arcane lanciate da Fuoco Stellare si dividono su massimo 3 bersaglio aggiuntivo al 80% dell'efficacia e forniscono 1 accumulo di Raccolta del Chiaro di Luna. Lanciare Furia di Elune o Luna Piena consuma Raccolta del Chiaro di Luna per aumentare i danni inflitti del 4% per accumulo per 12 s."}
MultiLanguageSpellData['it'][1236991] = {name = "Divoramento Vuoto", additional_info = "[q0][Item Effect]Portata di 100 m\nIstantaneo\n[q]Subire danni ha un'alta probabilità di permettere di divorare l'essenza dei nemici vicini, infliggendo 1923 danni da ombra suddivisi tra loro e rigenerando salute pari al 150% dei danni inflitti.\n\n I danni fatali che non superano 18656 ti riportano invece al 20% della salute massima e ti ricostituiscono in uno stato di vuoto instabile per 6 s. Rigenerare oltre il 65% della salute massima stabilizza la forma ed evita la morte. Può attivarsi solo una volta ogni 8 min. Il Nucleo non può infliggere danni durante la ricarica."}
