MultiLanguageSpellData['it'][1244402] = {name = "Cannocchiale del Cacciatore d'Essenza", additional_info = "Cannocchiale del Cacciatore d'Essenza Livello 80\n[q0][Item Effect]Circa 10 apparenze ogni minuto\n[q]I colpi critici inferti con incantesimi e abilità a distanza hanno un'alta probabilità di fornire Cacciatore Arcano fino a 5 volte, aumentando l'indice di critico di 14 per ogni accumulo per 8 s."}
MultiLanguageSpellData['it'][1244405] = {name = "Cella Eterea Manaforgiata", additional_info = "Cella Eterea Manaforgiata Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Le abilità di cura hanno una probabilità di potenziare la Cella Eterea, aumentando l'indice di maestria di 239 , riducendolo poi di ( 239 / 15) ogni secondo. Dura 15 s."}
MultiLanguageSpellData['it'][1244406] = {name = "Garza dell'Etere Simbiotica", additional_info = "Garza dell'Etere Simbiotica Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Bloccare, parare o schivare fornisce una probabilità di attivare la garza, facendo sì che infligga 1430 danni da arcano suddivisi tra i nemici vicini e ti fornisca uno scudo che assorbe 8283 danni subiti per 15 s."}
MultiLanguageSpellData['it'][1244410] = {name = "Mangiatore di Essenza Incorporeo", additional_info = "Mangiatore di Essenza Incorporeo Livello 80\n[q0][Item Effect]Portata di 50 m\n{Istantaneo} {2 min di recupero}\n[q]Strappa l'essenza magica dal bersaglio e la consuma, infliggendo ( 612 * 1 ) danni da arcano e aumentando la statistica secondaria più bassa di 247 per 20 s.\n\n Se il bersaglio è un Etereo, viene invece aumentata la statistica secondaria più alta."}
MultiLanguageSpellData['it'][1244414] = {name = "Rituale Erratico", additional_info = "3 s di lancio\n[q]L'incantatore richiama K'aresh e fa sì che gli spiriti eterei si muovano verso l'esterno in modo irregolare, infliggendo danni da arcano e stordendo i nemici sulla traiettoria."}
MultiLanguageSpellData['it'][1244415] = {name = "Rituale Erratico", additional_info = nil}
MultiLanguageSpellData['it'][1244417] = {name = "Spirito del Mana Distorto", additional_info = "Spirito del Mana Distorto Livello 80\n[q0][Item Effect]Circa 10 apparenze ogni minuto\n[q]I tuoi incantesimi e le abilità di cura hanno una probabilità molto alta di evocare uno Spirito del Mana Distorto che combatte al tuo fianco per 10 s. Lo Spirito del Mana Distorto cura periodicamente un alleato casuale vicino di ( 515 * 1 ). Le sovracure vengono convertite in uno scudo che assorbe i danni subiti per 5 s."}
