MultiLanguageSpellData['it'][1245357] = {name = "Grifone di Norderon Adornato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cavalieri di Grifoni più anziani e i Gran Sciamani dei Granmartello di Norderon adornavano spesso i grifoni con decorazioni piumate che ne indicavano il rango e lo stato.\"\nEmporio"}
MultiLanguageSpellData['it'][1245358] = {name = "Grifone di Picco dell'Aquila del Gran Sciamano", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli antichi sciamani dei Granmartello che incontrarono i grifoni per la prima volta credevano che fossero spiriti elementali in forma mortale. Questo incontro sarebbe rimasto impresso sul clan Granmartello nelle generazioni a venire.\"\nEmporio"}
MultiLanguageSpellData['it'][1245359] = {name = "Grifone delle Alture dalle Piume Cineree", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Secondo il folclore dei Granmartello, il piumaggio arancione dei grifoni sarebbe un tratto ereditario tramandato dal loro retaggio elementale.\"\nEmporio"}
MultiLanguageSpellData['it'][1245360] = {name = "Missile", additional_info = nil}
MultiLanguageSpellData['it'][1245361] = {name = "Guida dei Cieli Alardente", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Dalle colline di Khaz Modan, ne seguimmo le ali infuocate, una torcia diretta a nord che attraversava il cupo cielo estivo.\" - Il pellegrinaggio del Primo Saggio Selvaggio\nEmporio"}
MultiLanguageSpellData['it'][1245370] = {name = "Calcabrezza Irascibile", additional_info = "1.5 s di lancio\n[q]Evoca e congeda il tuo Calcabrezza Irascibile.\n[q]\"Questo talbuk resta una cavalcatura cocciuta e ostinata anche dopo aver familiarizzato col suo cavaliere. Occhio se le sali in groppa.\"\nEmporio"}
MultiLanguageSpellData['it'][1245376] = {name = "Cacciatore Arcano", additional_info = "[q0][Item Effect]Istantaneo\n[q]I colpi critici inferti con incantesimi e abilità a distanza hanno un'alta probabilità di fornire Cacciatore Arcano fino a 5 volte, aumentando l'indice di critico di 14 per ogni accumulo per 8 s."}
MultiLanguageSpellData['it'][1245377] = {name = "Schieramento Rilocatori", additional_info = "Istantaneo\n[q]So'azmi piazza una coppia di Rilocatori per confondere i nemici.\n Quando un personaggio tocca un Rilocatore, viene istantaneamente teletrasportato sull'altro Rilocatore corrispondente."}
MultiLanguageSpellData['it'][1245384] = {name = "Inferno Vile", additional_info = "Portata illimitata\nIstantaneo\n[q]Velaryn avvolge l'arena nelle fiamme, infliggendo 843230 danni da fuoco istantaneamente a tutti i personaggi e 182700 danni da fuoco aggiuntivi ogni 0.5 s per 15 s quando crea ogni pilastro dell'inferno. Si accumula.\n\n Le fiamme infliggono 8435981 danni da fuoco ogni 1 s a tutti i personaggi che entrano nella tempesta di fuoco."}
MultiLanguageSpellData['it'][1245397] = {name = "Cella Eterea Manaforgiata", additional_info = "[q0][Item Effect]Istantaneo\n[q]Le abilità di cura hanno una probabilità di potenziare la Cella Eterea, aumentando l'indice di maestria di 239 , riducendolo poi di ( 239 / 15) ogni secondo. Dura 15 s."}
MultiLanguageSpellData['it'][1245422] = {name = "Tsunami Arcano", additional_info = "Portata illimitata\nIstantaneo\n[q]La Vincolatrice d'Anime colpisce con rabbia il bersaglio primario, infliggendo 0 danni da arcano ogni 5.2 s per fino all'annullamento. Il personaggio colpito subisce il 10 % di danni aggiuntivi da Sferzata Mistica e subisce il 7 % di danni fisici aggiuntivi per 45 s."}
