MultiLanguageSpellData['it'][1245430] = {name = "Infusione Arcana", additional_info = "Istantaneo\n[q]L'incantatore infonde i personaggi entro 60 m con l'energia arcana, infliggendo 35 danni da arcano istantaneamente e 9 danni da arcano aggiuntivi ogni 1 s per 10 s.\n\n Inoltre, i bachi da seta nascenti entro 60 m subiscono Morsi Arcani ."}
MultiLanguageSpellData['it'][1245431] = {name = "Garza dell'Etere Simbiotica", additional_info = "[q0][Item Effect]Istantaneo\n[q]Bloccare, parare o schivare fornisce una probabilità di attivare la garza, facendo sì che infligga 1430 danni da arcano suddivisi tra i nemici vicini e ti fornisca uno scudo che assorbe 8283 danni subiti per 15 s."}
MultiLanguageSpellData['it'][1245440] = {name = "Pietra del Vuoto di K'aresh", additional_info = "[q0][Item Effect]2.5 s di lancio\n[q]Infonde l'armatura con una debole eco del vuoto, sbloccando effetti visivi aggiuntivi per alcuni set di classe della Manaforgia Omega.\n\n L'effetto è a livello di Brigata."}
