MultiLanguageSpellData['it'][1249462] = {name = "Accordo - Cartello Zo", additional_info = "[q0][Item Effect]Istantaneo\n[q]Stipula un accordo con il Cartello Zo che ti consente di definirti uno di loro (per una settimana).\n\n Contratto della Brigata\n Si può stipulare un accordo con un solo Cartello a settimana. L'effetto è condiviso con la Brigata."}
MultiLanguageSpellData['it'][1249463] = {name = "[q3]Accordo - Cartello Zo", additional_info = "3.5 s di lancio\nReagenti:\nCartapecora Fresca , Strumento Manaforgiato , Inchiostro Assolato (25)\nFazione:\nVandali della Manaforgia\nFama:\n8\nZona:\nPresidio Ombrale\n\n[q3]Accordo - Cartello Zo\n[q2]Usa: Stipula un accordo con il Cartello Zo che ti consente di definirti uno di loro (per una settimana).\n\n Contratto della Brigata\n Si può stipulare un accordo con un solo Cartello a settimana. L'effetto è condiviso con la Brigata.\n70\n[q]\"Un \"contratto\" di breve durata scritto grazie alla competenza in Runografia con cui una Brigata giura lealtà a un Cartello di Alienatori.\""}
MultiLanguageSpellData['it'][1249464] = {name = "Dono di Elune", additional_info = "[q0][Item Effect]Istantaneo\n[q]Affinità Animale, Sopravvivenza\nAumenta i danni inflitti da Bomba di Fuocobrado del 10%. Quando Tempesta Lunare termina, fornisce Dono di Elune, che fa sì che 2 lanci successivi di Bomba di Fuocobrado infliggano danni da arcano e i danni iniziali inflitti siano aumentati del 150%.\n\nPrecisione di Tiro\nAumenta i danni inflitti da Rapidità di Tiro del 25%. Quando Tempesta Lunare termina, fornisce Dono di Elune, che fa sì che 2 lanci successivi di Tiro Mirato infliggano danni da arcano e i danni inflitti siano aumentati del 10%."}
