MultiLanguageSpellData['it'][1250314] = {name = "Bocciolo Fantasma", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il Bocciolo Fantasma è il residuo energetico della flora nativa di K'aresh, impossibile da incorporare nelle ricette degli Algari.\n\n È invece possibile scambiare il Bocciolo Fantasma al mercato con altri materiali Algari. I prezzi cambiano ogni giorno, quindi con un po' di pazienza si possono ottenere le offerte migliori!"}
MultiLanguageSpellData['it'][1250317] = {name = "Bocciolo Fantasma Rigoglioso", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il Bocciolo Fantasma è il residuo energetico della flora nativa di K'aresh, impossibile da incorporare nelle ricette degli Algari.\n\n È invece possibile scambiare il Bocciolo Fantasma al mercato con altri materiali Algari. I prezzi cambiano ogni giorno, quindi con un po' di pazienza si possono ottenere le offerte migliori!\n\n Alcuni esemplari di Bocciolo Fantasma sono risultati notevolmente più grandi del previsto. È una delle poche piante sopravvissute alle spietate distese di K'aresh, nota perché le varietà più grandi prosperavano nei rigogliosi ambienti delle foreste indomabili."}
MultiLanguageSpellData['it'][1250351] = {name = "Deposito Desolato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]I minatori in cerca di fortuna su K'aresh possono trovare solo i miseri depositi di un mondo devastato. Sebbene questo minerale non abbia alcuna utilità per l'artigianato degli Algari, gli abitanti di Tazavesh danno un certo valore alle macerie che possono essere estratte."}
MultiLanguageSpellData['it'][1250356] = {name = "Deposito Desolato Ricco", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]I minatori in cerca di fortuna su K'aresh possono trovare solo i miseri depositi di un mondo devastato. Sebbene questo minerale non abbia alcuna utilità per l'artigianato degli Algari, gli abitanti di Tazavesh danno un certo valore alle macerie che possono essere estratte.\n\nA volte dei depositi di grandi dimensioni emergono da sottoterra, con grande gioia dei minatori che lavorano per il pane quotidiano."}
