MultiLanguageSpellData['it'][1251545] = {name = "Mietitura Eterea", additional_info = "Istantaneo\nCirca 2 apparenze ogni minuto\n[q]Gli incantesimi e le abilità d'attacco hanno una probabilità di concentrare le energie latenti tutt'intorno e infliggere danni da arcano suddivisi tra il bersaglio e i nemici vicini. I nemici con meno del 35% della salute massima subiscono il 20% di danni aggiuntivi.\n(100ms di recupero)"}
MultiLanguageSpellData['it'][1251549] = {name = "Ricostruzione Eterea", additional_info = "Istantaneo\nCirca 2 apparenze ogni minuto\n[q]Le abilità e gli incantesimi benefici hanno una probabilità di radunare l'energia dormiente per curare un alleato ferito. Le sovracure fornite dall'effetto forniscono uno scudo che assorbe danni subiti.\n(100ms di recupero)"}
